/**
 * Histogram fixtures.
 *
 * The samples are generated by a fixed-seed integer LCG rather than pasted as
 * literals: a thousand hand-typed numbers cannot be reviewed, and the
 * generator below is pure arithmetic with no `Math.random` and no clock, so
 * the fixture is byte-stable across machines and runs.
 *
 * Degenerate cases (n < 4, zero range, bin explosion, count mismatch) live in
 * `tests/histogram.test.ts`, not here: a fixture that throws would break the
 * invariant sweep, which layouts every registered fixture automatically.
 */

import { registerFixtures } from '../../../fixtures/registry';
import type { Fixture } from '../../registry';
import type { HistogramData, HistogramOptions } from './types';

/**
 * Numerical Recipes' 32-bit LCG. Deterministic, seedable, and good enough to
 * shape a demo distribution; nothing statistical depends on its quality.
 */
function lcg(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return state / 0x100000000;
  };
}

/** Sum of three uniforms — a cheap, bounded, symmetric bell. */
function bell(next: () => number): number {
  return (next() + next() + next()) / 3;
}

function orderValues(): number[] {
  const next = lcg(20260725);
  // Right-skewed: the cube pulls the mass toward the low end and stretches a
  // thin tail to the right, which is what order values actually look like.
  return Array.from({ length: 240 }, () => Math.round(200 + 2200 * Math.pow(next(), 4)));
}

function cycleTimes(): number[] {
  const next = lcg(4242);
  // Whole days: the measure is discrete, so the fixture authors a width of 1
  // rather than letting a rule pick 2.5 days.
  return Array.from({ length: 180 }, () => 1 + Math.round(13 * Math.pow(bell(next), 1.4)));
}

function bimodalWithFarOutlier(): number[] {
  const next = lcg(99001);
  const sample = Array.from({ length: 999 }, (_, index) => {
    const mode = index % 5 < 3 ? 320 : 780;
    return Math.round(mode + 190 * (bell(next) - 0.5));
  });
  // One order roughly 25x the mass. Every equal-width histogram of this sample
  // is compressed into a handful of bins — that is not a rendering failure,
  // it is what a single extreme observation does to a distribution, and the
  // message title says so.
  sample.push(14000);
  return sample;
}

export const fixtures: Fixture<HistogramData, HistogramOptions>[] = [
  {
    id: 'order-value-distribution',
    title: 'Order value is heavily right-skewed: half of all orders fall in the two lowest bins',
    kind: 'example',
    tags: ['interaction'],
    hover: { owner: { categoryId: '["bin",0,250]' } },
    data: { observations: orderValues() },
    options: {
      title: 'Order value is heavily right-skewed: half of all orders fall in the two lowest bins',
      subtitle: { measure: 'Order value', period: 'FY25' },
      unit: '$',
      source: 'Order book extract',
      bins: 'auto',
      axisTitles: { y: 'Orders' },
    },
  },
  {
    id: 'cycle-time-days',
    title: 'Cycle time peaks in the six-to-eight-day band and tails off by day thirteen',
    kind: 'example',
    data: { observations: cycleTimes() },
    options: {
      title: 'Cycle time peaks in the six-to-eight-day band and tails off by day thirteen',
      subtitle: { measure: 'Order-to-ship cycle time', period: 'FY25' },
      unit: 'days',
      source: 'Fulfilment log',
      // Whole days are the measurement grid; an authored width skips the snap.
      bins: { width: 1 },
      axisTitles: { y: 'Orders' },
    },
  },
  {
    id: 'order-value-eur-formatted',
    title: 'Formatted in euro: the bin edges carry the currency, the bar heights are counts',
    kind: 'torture',
    data: { observations: orderValues() },
    options: {
      title: 'Formatted in euro: the bin edges carry the currency, the bar heights are counts',
      subtitle: { measure: 'Order value', period: 'FY25' },
      // No unit: the format prints the euro sign on every edge.
      source: 'Order book extract',
      // The two axes of a histogram carry different quantities. Applied to
      // both, this format would make the count labels read "$42": `format`
      // describes the MEASURE, so it prints the edges and never the frequencies.
      // One locale on the exhibit, the subtitle's English, and a round
      // authored width the caption can print as it is.
      format: '$1,234',
      bins: { width: 250 },
      axisTitles: { y: 'Orders' },
      size: { width: 960, height: 540 },
    },
  },
  {
    id: 'bimodal-with-far-outlier',
    title: 'One $14,000 order stretches the axis over 40 bins; 999 of 1,000 orders sit in the first three',
    kind: 'torture',
    data: { observations: bimodalWithFarOutlier() },
    options: {
      title: 'One $14,000 order stretches the axis over 40 bins; 999 of 1,000 orders sit in the first three',
      subtitle: { measure: 'Order value', period: 'FY25' },
      unit: '$',
      source: 'Order book extract',
      // 'auto' answers 138 bins here: the Freedman-Diaconis width is tied to
      // the tight mass while the range is set by the single far observation.
      // That is arithmetically right and visually a smear of hairlines, so
      // this fixture shows the caller overriding it — which is exactly the
      // decision the method note has to make visible.
      // A round width from 0, so the 14,000 maximum closes the fortieth bin.
      bins: { width: 350, anchor: 0 },
      size: { width: 960, height: 540 },
    },
  },
];

// Coverage: the automatic width left unsnapped, and the binning rule stated.
const orderValueFixture = fixtures.find((fixture) => fixture.id === 'order-value-distribution')!;
fixtures.push({
  ...orderValueFixture,
  kind: 'torture', id: 'unsnapped-bins-method-note',
  title: 'The automatic bin width as computed, not snapped to a round number, with the binning rule stated',
  tags: ['coverage'],
  options: { ...orderValueFixture.options, binSnap: false, methodNote: true },
});

fixtures.push({
  id: 'localized-binning',
  title: 'Authored binning wording under a German locale',
  kind: 'torture',
  tags: ['coverage'],
  data: { observations: [0, 0.1, 0.4, 0.9, 1.1, 1.4] },
  options: {
    title: 'The values fall into three bins',
    locale: { language: 'de' }, bins: { width: 0.5, anchor: 0 }, methodNote: true,
    strings: { histogramBins: '{count} bins, each {about}{width} wide, from {from} to {to}; lower edge included' },
  },
});

registerFixtures('histogram', fixtures);
